{"op":"define","frontend":"flow","source":"word customer.renewal-balance(customer: Customer, subscription: Subscription) -> Float {
    effects none
    let balance = customer::discounted-balance(customer)
    if subscription::annual-renewable?(subscription) {
        float::multiply(balance, 0.95)
    } else {
        balance
    }
}

test customer.renewal-balance/premium-annual-renewable {
    customer::renewal-balance(
        customer::new("premium", 100.0),
        subscription::new("annual", true)
    ) => 85.5
}

test customer.renewal-balance/standard-annual-renewable {
    customer::renewal-balance(
        customer::new("standard", 100.0),
        subscription::new("annual", true)
    ) => 95.0
}

